import { formatEuros } from './money.js';
import { getCustomer } from './customers.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text for display to a customer.
 * @param {{ customerId: string, issueDate: string, status: string, number?: string, dueDate?: string, lines: Array, voucher?: object, payments?: Array }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  // Build the invoice number line
  const numberLine = invoice.number ? invoice.number : 'DRAFT';

  // Build line items with optional discounts
  const lineItems = invoice.lines.map((line) => {
    const total = lineTotal(line);
    const discount = lineDiscount(line);
    const lineStr = `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
    if (discount > 0) {
      return `${lineStr} (${line.discountPercent}% off: -${formatEuros(discount)})`;
    }
    return lineStr;
  });

  // Build totals
  const totals = invoiceTotals(invoice);

  // Assemble the full text
  const outputLines = [numberLine, customerName, ...lineItems];

  // Add voucher if present
  if (totals.voucher > 0) {
    outputLines.push(`Voucher: -${formatEuros(totals.voucher)}`);
  }

  // Add VAT if present
  if (totals.vat > 0) {
    outputLines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  outputLines.push(`Total: ${formatEuros(totals.total)}`);

  // Add due date if present
  if (invoice.dueDate) {
    outputLines.push(`Due: ${invoice.dueDate}`);
  }

  // Add paid amount if there are payments
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, payment) => sum + payment.amount, 0);
    outputLines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return outputLines.join('\n');
}

