    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'WORKSHOP-DAY', qty: 2 },
    ],
  });

  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  // DEV-HOUR: 3 × 9500 = 28500 cents = €285.00, VAT (21%): 5985
  // WORKSHOP-DAY: 2 × 60000 = 120000 cents = €1,200.00, VAT (0%): 0
  // C-002 is standard tier (0% discount)
  // Subtotal: 148500, VAT: 5985
  // Total: 148500 + 5985 = 154485 cents = €1,544.85
  assert.match(lines[2], /3 × Development \(hour\) @ €95\.00 = €285\.00/);
  assert.match(lines[3], /2 × Brand workshop \(day, VAT exempt\) @ €600\.00 = €1,200\.00/);
  assert.equal(lines[4], 'VAT: €59.85');
  assert.equal(lines[5], 'Total: €1,544.85');
});

