test('renderInvoiceText shows all enhancements together', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const withVoucher = applyVoucher(invoiceResult.value, { code: 'PROMO', amount: 3000 });
  const issuedResult = issueInvoice(withVoucher.value, []);
  const paidResult = recordPayment(issuedResult.value, { amount: 40000, date: '2025-10-08' });

  const text = renderInvoiceText(paidResult.value);
  const lines = text.split('\n');

  // Verify structure
  assert(lines[0].match(/INV-/), 'Invoice number present');
  assert.match(lines[2], /10% off: -€95\.00/, 'Line discount shown');
  // C-001 is gold tier (5% discount), DES-HOUR line: 5 × €85 = €425, discount = €21.25
  assert.match(lines[3], /5% off: -€21\.25/, 'Tier discount shown');
  const voucherLine = lines.find(line => line.startsWith('Voucher:'));
  assert(voucherLine, 'Voucher line present');
  const totalLine = lines.find(line => line.startsWith('Total:'));
  assert(totalLine, 'Total line present');
  const dueLine = lines.find(line => line.startsWith('Due:'));
  assert(dueLine, 'Due line present');
  const paidLine = lines.find(line => line.startsWith('Paid:'));
  assert(paidLine, 'Paid line present');
  assert.match(paidLine, /€400\.00/, 'Paid amount correct');
});
